javas.java:

str def approvalLevel(int:amountWan) {
    if (amountWan >= 10000) {
        return "SASAC";
    } else if (amountWan >= 5000) {
        return "GROUP";
    } else if (amountWan >= 1000) {
        return "BOARD";
    } else if (amountWan >= 300) {
        return "EXECUTIVE";
    } else {
        return "INTERNAL";
    }
}


int def cappedApprovedWan(int:requestedWan, int:grantedWan, str:projectType) {
    int limit = grantedWan;
    if (requestedWan < limit) {
        limit = requestedWan;
    }
    if (projectType == "NON_MAIN") {
        if (limit > 3000) {
            limit = 3000;
        }
    }
    if (projectType == "FINANCIAL") {
        limit = 0;
    }
    if (projectType == "REAL_ESTATE") {
        limit = 0;
    }
    return limit;
}
